import 'package:flutter/material.dart';
import '../../data/database_helper.dart';
import '../../widgets/common_widgets.dart';

class CustomersScreen extends StatefulWidget { const CustomersScreen({super.key}); @override State<CustomersScreen> createState()=>_CustomersScreenState(); }
class _CustomersScreenState extends State<CustomersScreen>{
 final db=DatabaseHelper.instance, search=TextEditingController();
 final fields={for(final f in ['name','code','phone','mobile','address','credit_limit','balance'])f:TextEditingController()};
 List<Map<String,Object?>> customers=[];
 int? selectedId; String filter=''; bool active=true,suspended=false,managerApproval=false,busy=false,editing=true;
 @override void initState(){super.initState();reload();}
 @override void dispose(){search.dispose();for(final c in fields.values)c.dispose();super.dispose();}
 void msg(String s){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(s)));}
 Future<void> reload()async{try{final rows=await db.query('customers',orderBy:'name COLLATE NOCASE');if(mounted)setState(()=>customers=rows);}catch(e){msg('تعذر تحميل العملاء: $e');}}
 void clearForm(){setState((){selectedId=null;active=true;suspended=false;managerApproval=false;editing=true;for(final c in fields.values)c.clear();fields['credit_limit']!.text='0';fields['balance']!.text='0';});}
 void select(Map<String,Object?> row){setState((){selectedId=(row['id'] as num).toInt();for(final f in fields.keys){fields[f]!.text=(row[f]??'').toString();}active=((row['is_active'] as num?)?.toInt()??1)==1;suspended=((row['is_suspended'] as num?)?.toInt()??0)==1;managerApproval=((row['manager_approval'] as num?)?.toInt()??0)==1;editing=false;});}
 Future<void> save()async{if(fields['name']!.text.trim().isEmpty){msg('اسم العميل مطلوب');return;}final limit=double.tryParse(fields['credit_limit']!.text);if(limit==null||limit<0){msg('حد الدين يجب أن يكون رقمًا غير سالب');return;}setState(()=>busy=true);try{final d=<String,Object?>{'name':fields['name']!.text.trim(),'code':fields['code']!.text.trim().isEmpty?null:fields['code']!.text.trim(),'phone':fields['phone']!.text.trim(),'mobile':fields['mobile']!.text.trim(),'address':fields['address']!.text.trim(),'credit_limit':limit,'is_active':active?1:0,'is_suspended':suspended?1:0,'manager_approval':managerApproval?1:0};if(selectedId==null){selectedId=await db.insert('customers',d);msg('تم إنشاء العميل');}else{await db.update('customers',d,where:'id=?',whereArgs:[selectedId]);msg('تم تحديث بيانات العميل');}await reload();final row=customers.where((r)=>(r['id'] as num).toInt()==selectedId);if(row.isNotEmpty)select(row.first);}catch(e){msg('تعذر حفظ العميل: $e');}finally{if(mounted)setState(()=>busy=false);}}
 Future<void> deleteCustomer()async{if(selectedId==null)return;final yes=await showDialog<bool>(context:context,builder:(c)=>AlertDialog(title:const Text('حذف العميل'),content:const Text('قد تمنع الفواتير والأرصدة المرتبطة حذف العميل.'),actions:[TextButton(onPressed:()=>Navigator.pop(c,false),child:const Text('إلغاء')),FilledButton(onPressed:()=>Navigator.pop(c,true),child:const Text('حذف'))]));if(yes!=true)return;try{await db.delete('customers',where:'id=?',whereArgs:[selectedId]);clearForm();await reload();msg('تم حذف العميل');}catch(e){msg('لا يمكن حذف عميل مرتبط بفواتير أو أرصدة: $e');}}
 @override Widget build(BuildContext context){final rows=customers.where((r)=>filter.isEmpty||r.values.any((v)=>v.toString().toLowerCase().contains(filter.toLowerCase()))).toList();return Padding(padding:const EdgeInsets.all(16),child:Column(children:[
 Wrap(spacing:8,runSpacing:8,children:[ActionButton('جديد',icon:Icons.add,onPressed:clearForm),ActionButton('حفظ',icon:Icons.save,primary:true,onPressed:busy?()=>{}:save),ActionButton('تعديل',icon:Icons.edit,onPressed:()=>selectedId==null?msg('اختر عميلًا من القائمة أولًا'):setState(()=>editing=true)),ActionButton('تفريغ',icon:Icons.cleaning_services,onPressed:clearForm),ActionButton('تحديث',icon:Icons.refresh,onPressed:reload),ActionButton('حذف',icon:Icons.delete_outline,onPressed:deleteCustomer)]),const SizedBox(height:12),
 Expanded(child:Row(crossAxisAlignment:CrossAxisAlignment.stretch,children:[
 SizedBox(width:390,child:Card(child:Padding(padding:const EdgeInsets.all(12),child:Column(crossAxisAlignment:CrossAxisAlignment.stretch,children:[TextField(controller:search,decoration:const InputDecoration(labelText:'بحث عام عن العملاء',prefixIcon:Icon(Icons.search)),onChanged:(v)=>setState(()=>filter=v.trim())),const SizedBox(height:10),Row(children:[Expanded(child:OutlinedButton.icon(onPressed:()=>setState(()=>filter=search.text.trim()),icon:const Icon(Icons.search),label:const Text('بحث'))),const SizedBox(width:6),IconButton(onPressed:reload,tooltip:'تحديث',icon:const Icon(Icons.refresh))]),const Divider(),Expanded(child:rows.isEmpty?const Center(child:Text('لا توجد نتائج')):SingleChildScrollView(scrollDirection:Axis.horizontal,child:DataTable(columns:const[DataColumn(label:Text('الاسم')),DataColumn(label:Text('الكود')),DataColumn(label:Text('الجوال')),DataColumn(label:Text('الرصيد')),DataColumn(label:Text('الحالة'))],rows:rows.map((r)=>DataRow(selected:(r['id'] as num).toInt()==selectedId,onSelectChanged:(_)=>select(r),cells:[DataCell(Text((r['name']??'').toString())),DataCell(Text((r['code']??'—').toString())),DataCell(Text((r['mobile']??'—').toString())),DataCell(Text((r['balance']??0).toString())),DataCell(Text(((r['is_active'] as num?)?.toInt()??1)==1?'نشط':'غير نشط'))])).toList()))]))),
 const SizedBox(width:12),Expanded(child:Card(child:ListView(padding:const EdgeInsets.all(18),children:[
 Text(selectedId==null?'بيانات عميل جديد':'بيانات العميل #$selectedId',style:Theme.of(context).textTheme.titleLarge),const SizedBox(height:16),
 Wrap(spacing:12,runSpacing:12,children:[
 for(final e in fields.entries)SizedBox(width:e.key=='address'?500:240,child:TextField(controller:e.value,readOnly:e.key=='balance'||!editing,keyboardType:e.key=='credit_limit'||e.key=='balance'?const TextInputType.numberWithOptions(decimal:true):TextInputType.text,maxLines:e.key=='address'?2:1,decoration:InputDecoration(labelText:switch(e.key){'name'=>'اسم العميل *','code'=>'كود العميل','phone'=>'الهاتف','mobile'=>'الجوال','address'=>'العنوان','credit_limit'=>'حد الدين / الائتمان','balance'=>'الرصيد الحالي (يُحدّث من الحركات)',_=>e.key}))),
 ]),
 const SizedBox(height:16),const Divider(),Text('البيانات الائتمانية والتحكم',style:Theme.of(context).textTheme.titleMedium),
 SwitchListTile(contentPadding:EdgeInsets.zero,title:const Text('حساب نشط'),subtitle:const Text('يمكن اختيار العميل في الفواتير'),value:active,onChanged:(v)=>setState(()=>active=v)),
 SwitchListTile(contentPadding:EdgeInsets.zero,title:const Text('إيقاف التعامل الائتماني'),subtitle:const Text('يمنع البيع الآجل للعميل عند الترحيل'),value:suspended,onChanged:(v)=>setState(()=>suspended=v)),
 SwitchListTile(contentPadding:EdgeInsets.zero,title:const Text('موافقة المدير'),subtitle:const Text('تسجيل موافقة إدارية على حساب العميل'),value:managerApproval,onChanged:(v)=>setState(()=>managerApproval=v)),
 const SizedBox(height:10),const Text('الرصيد الحالي للعرض فقط، ويُحدّث من فواتير البيع والتحصيلات؛ لا يُعدّل يدويًا من بطاقة العميل.',style:TextStyle(color:Colors.blueGrey)),
 ])))
 ]))
 ]));}
}
